export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// The targeting context a feature-flag provider needs to evaluate flags for
// a given user. Centralized here so anything that flips flags per-user (see
// src/lib/flags.ts) builds it from this one definition instead of every
// call site poking at User fields directly.
export type FeatureFlagContext = {
  kind: "user";
  key: string;
  email: string;
  name: string;
};

export function toFeatureFlagContext(user: User): FeatureFlagContext {
  return {
    kind: "user",
    key: user.id,
    email: user.email,
    name: user.name,
  };
}
